     1	#!/usr/bin/env node
     2	/** The MHPCO's counter clerk: reads a scenario from stdin, walks its steps in
     3	 *  order past the premium and claims offices, and writes the results to
     4	 *  stdout. Transport and JSON translation live here; no office rule does. */
     5	
     6	import { readFileSync } from "node:fs";
     7	import {
     8	  claim,
     9	  createPolicy,
    10	  quote,
    11	  type Customer,
    12	  type Incident,
    13	  type Item,
    14	  type Policy,
    15	} from "./claim-office.js";
    16	
    17	interface QuoteStep {
    18	  op: "quote";
    19	  items: Item[];
    20	}
    21	
    22	interface ClaimStep {
    23	  op: "claim";
    24	  policy: number;
    25	  incident: Incident;
    26	}
    27	
    28	type Step = QuoteStep | ClaimStep;
    29	
    30	interface Scenario {
    31	  customer: Customer;
    32	  steps: Step[];
    33	}
    34	
    35	type StepResult = { premium: number } | { payout: number; remainingCap: number };
    36	
    37	/** The policy a claim step names by the zero-based index of the quote step
    38	 *  that created it. */
    39	function namedPolicy(policies: Map<number, Policy>, step: ClaimStep): Policy {
    40	  const policy = policies.get(step.policy);
    41	  if (policy === undefined) {
    42	    throw new Error(`step ${step.policy} did not create a policy to claim against`);
    43	  }
    44	  return policy;
    45	}
    46	
    47	function settleScenario(scenario: Scenario): StepResult[] {
    48	  const policies = new Map<number, Policy>();
    49	  return scenario.steps.map((step, index) => {
    50	    if (step.op === "claim") {
    51	      return claim(namedPolicy(policies, step), step.incident);
    52	    }
    53	    const premium = quote(scenario.customer, step.items, policies.size);
    54	    policies.set(index, createPolicy(step.items));
    55	    return { premium };
    56	  });
    57	}
    58	
    59	function main(): void {
    60	  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
    61	  process.stdout.write(JSON.stringify({ results: settleScenario(scenario) }));
    62	}
    63	
    64	try {
    65	  main();
    66	} catch (error) {
    67	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    68	  process.exitCode = 1;
    69	}
