     1	/** The claims office: what the MHPCO pays out when an insured item is damaged.
     2	 *  Every decision here belongs to the claims handbook -- the deductible, the
     3	 *  special clauses, the cap on a policy -- and is revised independently of the
     4	 *  tariff that priced the policy. */
     5	
     6	import { insuranceValue, type Item } from "./item-catalog.js";
     7	import { amountPaidInMHPCOsFavour } from "./rounding.js";
     8	
     9	export interface Damage {
    10	  itemType: string;
    11	  amount: number;
    12	}
    13	
    14	export interface Incident {
    15	  cause: string;
    16	  damages: Damage[];
    17	}
    18	
    19	export interface Policy {
    20	  items: Item[];
    21	  /** What the MHPCO has already paid out on this policy against its cap. */
    22	  capConsumed: number;
    23	}
    24	
    25	export interface ClaimResult {
    26	  payout: number;
    27	  remainingCap: number;
    28	}
    29	
    30	const DEDUCTIBLE_PER_DAMAGE = 100;
    31	
    32	/** The MHPCO never pays out more than twice the sum a policy insures. */
    33	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    34	
    35	/** From enchantment level 8 upwards the handbook reimburses only half the
    36	 *  damage: powerful enchantments are held to attract their own misfortune.
    37	 *  This is the only clause the handbook reads *down* from full reimbursement,
    38	 *  so it outranks the dragon-material clause whenever both cover an item. */
    39	const HIGH_ENCHANTMENT_CLAUSE_THRESHOLD = 8;
    40	const HIGH_ENCHANTMENT_CLAUSE_SHARE = 0.5;
    41	
    42	/** The MHPCO opens a policy over the items a quote covered. */
    43	export function createPolicy(items: Item[]): Policy {
    44	  return { items, capConsumed: 0 };
    45	}
    46	
    47	/** The MHPCO bears its deductible against a damage; it never turns the
    48	 *  deductible round into a charge the customer owes the office. A damage
    49	 *  smaller than the deductible is simply not reimbursed. */
    50	function neverACharge(reimbursement: number): number {
    51	  return Math.max(reimbursement, 0);
    52	}
    53	
    54	/** Whether the handbook's high-enchantment clause covers a damaged item. */
    55	function fallsUnderHighEnchantmentClause(item: Item): boolean {
    56	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_THRESHOLD;
    57	}
    58	
    59	/** The amount of a damage the handbook reimburses, before the deductible is
    60	 *  kept back. Full reimbursement is what the office grants unless a clause cuts
    61	 *  it down, and the high-enchantment clause is the only clause that cuts.
    62	 *
    63	 *  The handbook's dragon-material clause -- damage to items made of dragon
    64	 *  material is fully reimbursed -- is therefore already honoured here: it grants
    65	 *  exactly what the default grants, so no dragon branch is written. Should a
    66	 *  future clause reduce reimbursement for some *other* reason, dragon material
    67	 *  would have to be read as an exemption from it, and would then need a branch
    68	 *  of its own. */
    69	function reimbursedAmount(damage: Damage, item: Item): number {
    70	  if (fallsUnderHighEnchantmentClause(item)) {
    71	    return damage.amount * HIGH_ENCHANTMENT_CLAUSE_SHARE;
    72	  }
    73	  return damage.amount;
    74	}
    75	
    76	/** The handbook's reimbursement decision for one damage event: the clauses
    77	 *  decide the reimbursed amount, from which the MHPCO keeps back its
    78	 *  deductible. */
    79	function reimbursementForDamage(damage: Damage, item: Item): number {
    80	  return neverACharge(reimbursedAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
    81	}
    82	
    83	/** One reported damage, matched to the covered item it refers to. */
    84	interface MatchedDamage {
    85	  damage: Damage;
    86	  item: Item;
    87	}
    88	
    89	/** Whether the office entertains a reported damage at all, judged on the entry
    90	 *  itself and without consulting the cover. A damage is a loss the customer
    91	 *  suffered, so an entry claiming a negative amount is not an understated claim
    92	 *  the office could settle at nothing -- it is not a damage report at all, and
    93	 *  the office refuses the whole claim rather than reading past it.
    94	 *
    95	 *  This is the office's admission policy, and it is revised independently of how
    96	 *  a report is read against the cover: a new ground of refusal is a rule added
    97	 *  here, and a change to how damages are assigned to covered items leaves it
    98	 *  untouched. */
    99	function refuseInadmissibleDamage(damage: Damage): void {
   100	  if (damage.amount < 0) {
   101	    throw new Error(`a damage report cannot claim a negative amount of ${damage.amount} G`);
   102	  }
   103	}
   104	
   105	/** Which covered item each reported damage refers to. The office reads a
   106	 *  damage report against the policy's *cover*: a damage names an item type, and
   107	 *  the office assigns it one of the items the policy covers of that type. Two
   108	 *  entries of the same type are two damages against two covered swords, not the
   109	 *  same sword claimed twice, so a matched item is struck off the cover and the
   110	 *  next entry of that type must find another.
   111	 *
   112	 *  A report naming an item the policy does not cover, or naming more items of a
   113	 *  type than the policy covers, fails here: that is a failure of the cover, not
   114	 *  of the entry's own form, so an unmatchable entry stops the claim rather than
   115	 *  being settled against nothing. */
   116	function matchDamagesToCover(policy: Policy, damages: Damage[]): MatchedDamage[] {
   117	  const unclaimedCover = [...policy.items];
   118	  return damages.map((damage) => {
   119	    const covered = unclaimedCover.findIndex((item) => item.type === damage.itemType);
   120	    if (covered < 0) {
   121	      throw new Error(
   122	        `the policy covers no further ${damage.itemType} for this damage report`,
   123	      );
   124	    }
   125	    const [item] = unclaimedCover.splice(covered, 1);
   126	    return { damage, item };
   127	  });
   128	}
   129	
   130	/** The damages of an incident the office admits to settlement: every entry is
   131	 *  first judged admissible on its own terms, then read against the policy's
   132	 *  cover. A report that fails either test is refused whole -- the office does
   133	 *  not settle the admissible part of a bad report. */
   134	function admitDamages(policy: Policy, damages: Damage[]): MatchedDamage[] {
   135	  damages.forEach(refuseInadmissibleDamage);
   136	  return matchDamagesToCover(policy, damages);
   137	}
   138	
   139	/** The sum a policy insures: the insurance values of all covered items. The
   140	 *  block discount on the premium does not reduce what the items are insured
   141	 *  for. */
   142	function insuranceSum(policy: Policy): number {
   143	  return policy.items.reduce((sum, item) => sum + insuranceValue(item), 0);
   144	}
   145	
   146	/** The most the MHPCO will ever pay out on a policy. */
   147	function payoutCap(policy: Policy): number {
   148	  return insuranceSum(policy) * CAP_MULTIPLE_OF_INSURANCE_SUM;
   149	}
   150	
   151	/** What the handbook reimburses for a whole incident: every admitted damage
   152	 *  settled on its own terms -- its own clauses, its own deductible -- and the
   153	 *  reimbursements added up. This is the claim before the cap is consulted; how
   154	 *  far the policy's cap bounds it is a separate decision. */
   155	function reimbursementForIncident(admitted: MatchedDamage[]): number {
   156	  return admitted.reduce(
   157	    (sum, { damage, item }) => sum + reimbursementForDamage(damage, item),
   158	    0,
   159	  );
   160	}
   161	
   162	/** What is left of a policy's cap: the cap itself, less what the MHPCO has
   163	 *  already paid out on it. */
   164	function remainingCap(policy: Policy): number {
   165	  return payoutCap(policy) - policy.capConsumed;
   166	}
   167	
   168	/** What the MHPCO actually pays for an incident: what the handbook reimburses,
   169	 *  but never more than the policy's cap still allows. A claim that asks for more
   170	 *  than is left is settled at what is left. */
   171	function settledPayout(policy: Policy, admitted: MatchedDamage[]): number {
   172	  const bounded = Math.min(reimbursementForIncident(admitted), remainingCap(policy));
   173	  return amountPaidInMHPCOsFavour(bounded);
   174	}
   175	
   176	/** The office's ledger entry against the policy: a settled payout consumes that
   177	 *  much of the policy's cap, once and for good. This is what makes a claim a
   178	 *  command rather than a calculation -- the cap a later claim finds is the cap
   179	 *  this one left behind. */
   180	function recordAgainstCap(policy: Policy, payout: number): void {
   181	  policy.capConsumed += payout;
   182	}
   183	
   184	/** The MHPCO settles one incident against a policy: it decides what the claim is
   185	 *  worth under the handbook and the policy's remaining cap, enters that payout
   186	 *  in the policy's ledger, and reports the payout with the cap that survives it.
   187	 *  Admitting the report against the cover comes first and on its own: a report
   188	 *  the office refuses is refused before any amount is decided, so whether a
   189	 *  claim is entertained at all changes independently of what it is worth.
   190	 *  Deciding the amount and recording it are separate acts here, so that a change
   191	 *  to how a payout is arrived at is necessarily also what gets recorded. */
   192	export function claim(policy: Policy, incident: Incident): ClaimResult {
   193	  const admitted = admitDamages(policy, incident.damages);
   194	  const payout = settledPayout(policy, admitted);
   195	  recordAgainstCap(policy, payout);
   196	  return { payout, remainingCap: remainingCap(policy) };
   197	}
================ src/item-catalog.ts
     1	/** The insured things the MHPCO knows, and the price-list facts that both the
     2	 *  premium office and the claims office read off the same catalogue entry.
     3	 *  Neither side owns this knowledge: a new item type is one catalogue change,
     4	 *  not a change to how premiums or payouts are decided. */
     5	
     6	export interface Item {
     7	  type: string;
     8	  material?: string;
     9	  enchantment?: number;
    10	  cursed?: boolean;
    11	}
    12	
    13	/** One row of the MHPCO price list: everything the office has decided about an
    14	 *  item type. Insurance value and base premium are quoted together, per type,
    15	 *  and are revised together when the office reprices a type. */
    16	interface CatalogueEntry {
    17	  insuranceValue: number;
    18	  basePremium: number;
    19	}
    20	
    21	/** Every component -- rune, moonstone -- is insured for the same sum and
    22	 *  carries the same base premium, independent of which component it is. */
    23	const COMPONENT: CatalogueEntry = { insuranceValue: 250, basePremium: 25 };
    24	
    25	/** The MHPCO price list. Every item type the office recognizes appears here
    26	 *  exactly once, so a new type is one row, never two half-entries. */
    27	const PRICE_LIST: Record<string, CatalogueEntry> = {
    28	  sword: { insuranceValue: 1000, basePremium: 100 },
    29	  amulet: { insuranceValue: 600, basePremium: 60 },
    30	  staff: { insuranceValue: 800, basePremium: 80 },
    31	  potion: { insuranceValue: 400, basePremium: 40 },
    32	  rune: COMPONENT,
    33	  moonstone: COMPONENT,
    34	};
    35	
    36	/** The price list's entry for an insured item. The MHPCO insures only what its
    37	 *  price list names, so a type the list does not carry is refused here rather
    38	 *  than priced: the office has no insurance value and no base premium to quote
    39	 *  for it, and both counters must refuse it for the same one reason. */
    40	function catalogueEntry(item: Item): CatalogueEntry {
    41	  const entry = PRICE_LIST[item.type];
    42	  if (entry === undefined) {
    43	    throw new Error(`the MHPCO price list knows no item of type "${item.type}"`);
    44	  }
    45	  return entry;
    46	}
    47	
    48	/** The sum the MHPCO insures an item for, per the price list. */
    49	export function insuranceValue(item: Item): number {
    50	  return catalogueEntry(item).insuranceValue;
    51	}
    52	
    53	/** The MHPCO price list's base premium for an insured item. */
    54	export function basePremium(item: Item): number {
    55	  return catalogueEntry(item).basePremium;
    56	}
    57	
    58	/** Two items are "alike" when they share this key. The MHPCO reads "alike"
    59	 *  as *the same type* -- a rune is alike another rune, but not a moonstone. */
    60	export function alikeKey(item: Item): string {
    61	  return item.type;
    62	}
